import{_ as t,o as i,c as r,a3 as e}from"./chunks/framework.Q4yG9rk_.js";const y=JSON.parse('{"title":"孔子十翼","description":"《易传》十篇——系辞、文言、说卦、序卦、杂卦（彖、象随六十四卦）——是易经从占卜之书走向义理之学的枢纽。","frontmatter":{"title":"孔子十翼","description":"《易传》十篇——系辞、文言、说卦、序卦、杂卦（彖、象随六十四卦）——是易经从占卜之书走向义理之学的枢纽。","category":"guide","aliases":["孔子十翼","十翼","易传","shi yi"]},"headers":[],"relativePath":"yijing/shi-yi/index.md","filePath":"yijing/shi-yi/index.md","lastUpdated":1789714390000}'),d={name:"yijing/shi-yi/index.md"};function h(n,a,o,l,s,u){return i(),r("div",null,[...a[0]||(a[0]=[e('<h1 id="孔子十翼" tabindex="-1">孔子十翼 <a class="header-anchor" href="#孔子十翼" aria-label="Permalink to &quot;孔子十翼&quot;">​</a></h1><p>「十翼」是《易传》的统称，传统归为孔子及其后学对《易经》的解释文字，好比为「经」插上的十只翅膀。</p><h2 id="是什么" tabindex="-1">是什么 <a class="header-anchor" href="#是什么" aria-label="Permalink to &quot;是什么&quot;">​</a></h2><p>十翼共七种、十篇：</p><table tabindex="0"><thead><tr><th>篇名</th><th>分篇</th><th>作用</th><th>本站形态</th></tr></thead><tbody><tr><td>彖传</td><td>上、下</td><td>释卦名、卦辞，断一卦之义</td><td><strong>随六十四卦</strong>（见卦页内嵌）</td></tr><tr><td>象传</td><td>上、下</td><td>释卦象与爻象，大象、小象</td><td><strong>随六十四卦</strong>（见卦页内嵌）</td></tr><tr><td>系辞传</td><td>上、下</td><td>易学总论，讲易理、易用</td><td>独立导读页</td></tr><tr><td>文言传</td><td>—</td><td>专释乾、坤两卦</td><td>独立导读页</td></tr><tr><td>说卦传</td><td>—</td><td>讲八卦的取象与方位</td><td>独立导读页</td></tr><tr><td>序卦传</td><td>—</td><td>讲六十四卦的次序之理</td><td>独立导读页</td></tr><tr><td>杂卦传</td><td>—</td><td>以对比方式点明各卦要义</td><td>独立导读页</td></tr></tbody></table><p>彖、象两传不单独成页：它们本就附着在每一卦的卦辞、爻辞之下，本站已把彖、象原文与字词释义内嵌进各卦页（如 <a href="/Dao/yijing/hexagrams/03-shuileizhun">屯卦</a>），随逐卦阅读即是读彖、象。</p><h2 id="为什么重要" tabindex="-1">为什么重要 <a class="header-anchor" href="#为什么重要" aria-label="Permalink to &quot;为什么重要&quot;">​</a></h2><p>《易经》原本是占筮之书。正是十翼把卦爻辞背后的<strong>变化之理、忧患意识、修身之道</strong>揭示出来，使它成为一部哲学经典。后来的「义理」一脉，源头就在十翼。</p><h2 id="怎么读" tabindex="-1">怎么读 <a class="header-anchor" href="#怎么读" aria-label="Permalink to &quot;怎么读&quot;">​</a></h2><p>建议顺序：</p><ol><li>先读《系辞传》（<a href="/Dao/yijing/shi-yi/xi-ci-zhuan-shang">上</a> → <a href="/Dao/yijing/shi-yi/xi-ci-zhuan-xia">下</a>）——它是进入易学思想的总纲；</li><li>再读《<a href="/Dao/yijing/shi-yi/shuo-gua-zhuan">说卦传</a>》《<a href="/Dao/yijing/shi-yi/xu-gua-zhuan">序卦传</a>》《<a href="/Dao/yijing/shi-yi/za-gua-zhuan">杂卦传</a>》——建立卦的骨架与关系；</li><li>读《<a href="/Dao/yijing/shi-yi/wen-yan-zhuan">文言传</a>》——看乾、坤两卦被讲透的样板；</li><li>最后随逐卦阅读，回到各卦页里的《彖传》《象传》，以及两篇传之间的互相印证。</li></ol><h2 id="十翼各篇" tabindex="-1">十翼各篇 <a class="header-anchor" href="#十翼各篇" aria-label="Permalink to &quot;十翼各篇&quot;">​</a></h2><ul><li><a href="/Dao/yijing/shi-yi/xi-ci-zhuan-shang">系辞上传</a> — 易之体：易简、观象系辞、大衍之数、一阴一阳之谓道</li><li><a href="/Dao/yijing/shi-yi/xi-ci-zhuan-xia">系辞下传</a> — 易之用：卦爻之变、观象制器、三陈九卦、穷变通久</li><li><a href="/Dao/yijing/shi-yi/wen-yan-zhuan">文言传</a> — 专释乾坤：元亨利贞四德、大人之德、坤道积善</li><li><a href="/Dao/yijing/shi-yi/shuo-gua-zhuan">说卦传</a> — 八卦取象与方位：乾坤生六子、近取远取、先后天方位</li><li><a href="/Dao/yijing/shi-yi/xu-gua-zhuan">序卦传</a> — 卦序之理：从乾坤到未济的连锁逻辑</li><li><a href="/Dao/yijing/shi-yi/za-gua-zhuan">杂卦传</a> — 卦德速览：乾刚坤柔，比乐师忧</li></ul><h2 id="我的理解" tabindex="-1">我的理解 <a class="header-anchor" href="#我的理解" aria-label="Permalink to &quot;我的理解&quot;">​</a></h2><p>十翼这一轮，是和易师一篇一篇读下来的：先系辞上下，再文言、说卦，最后落到序卦与杂卦。读之前我以为「传」只是注解，读完才发现，它其实是在教人怎么读「经」。</p><p><strong>系辞</strong>让我停得最久。「易简而天下之理得矣」——越根本的东西越简单，王公悟之得治国之理，平民悟之得日用之理，万物得之得生长之理。也是从这里我才分清「玩」和「研究」是两回事：研究是为了某个目的去做，感到的都是目的的投影；玩是无心之感，才有咸，才有那些始料未及的启发。还有一处反转：我原先把「无咎」读成「没有过错」，重读才知道是「善补过」——不是结果上的「我现在没事了」，而是认知上的「我知道自己现在在做什么」。顺着这个想下去，善补过最难的一步是知过，要知过才能改；同样经历的时间，带着自省和不带自省，最后会走到完全不同的地方。</p><p><strong>文言</strong>专讲乾坤，把这两卦讲透了，其余六十二卦才有参照。我留下的是两点：乾讲创始、坤讲承接，不是二选一；「柔」不等于弱，「不争」也不等于没有价值，安静的承载同样能产生刚健而持久的结果。</p><p><strong>说卦</strong>把八卦的取象和方位铺开，让我明白取象重意不重表——那些象是示例，不是穷举。先天讲对待、后天讲流行，一个是结构，一个是运行，用的时候知其然也知其所以然，不必执着谁才是唯一根本。</p><p><strong>序卦</strong>给了我一个很实用的意识：每一局都会带出下一局。读它之后，我比较不容易把困难看成凭空降临，也不太会把顺利当成理所当然；在既济处保留一点对未济的清醒，在未济处也不放弃下一次通达的可能。</p><p><strong>杂卦</strong>的提醒最短，也最锋利：不要让一个标签替代真实观察，收拢之后还要回到卦象、时位、关系和行动里去验证。对照也往往比单独定义更有力量——人只想「乐」而不愿「忧」，只想「益」而不肯「损」，把两面放在一起，才更接近变化中的完整。</p><p>这几篇读下来，最直接的变化是我看《易》的方式变了：它不再是一堆散着的卦，而是一套彼此咬着的东西——象、辞、变、占各有各的位置。而真正要落实的地方，其实很朴素：「默而成之，不言而信，存乎德行。」不急着证明自己懂了，让读到的东西慢慢进到言语、判断和日用里。</p><h2 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to &quot;延伸阅读&quot;">​</a></h2><ul><li>与「文王六十四卦」对照：卦爻辞是「经」，十翼是「传」</li><li>与「义理」对照：义理派正是以十翼为宗</li><li>彖、象随逐卦：见 <a href="/Dao/yijing/hexagrams/">六十四卦目录</a></li></ul>',23)])])}const p=t(d,[["render",h]]);export{y as __pageData,p as default};
